import re
from pathlib import Path

import pytesseract
from openpyxl import Workbook
from PIL import Image, ImageFilter, ImageOps

IMAGE_DIR = Path("/app/workspace/dataset/img")
OUTPUT_XLSX = Path("/app/workspace/stat_ocr.xlsx")

PRIORITY_KEYWORDS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE",
     "BALANCE DUE", "NETT TOTAL", "NET TOTAL"],
]

EXCLUSION_KEYWORDS = [
    "SUBTOTAL",
    "SUB TOTAL",
    "SUB-TOTAL",
    "TAX",
    "GST",
    "SST",
    "DISCOUNT",
    "CHANGE",
    "CASH TENDERED",
]

AMOUNT_RE = re.compile(r"(?<![\d.])(\d{1,3}(?:,\d{3})+(?:\.\d{1,2})|\d+\.\d{2})(?![\d])")

DATE_PATTERNS = [
    (re.compile(r"\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})\b"), "dmy"),
    (re.compile(r"\b(\d{4})[/\-\.](\d{1,2})[/\-\.](\d{1,2})\b"), "ymd"),
    (re.compile(r"\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2})\b"), "dmy2"),
    (re.compile(r"\b(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{4})\b"), "dMy"),
    (re.compile(r"\b([A-Za-z]{3,9})\s+(\d{1,2})[,\s]+(\d{4})\b"), "Mdy"),
]

MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}


def preprocess(img):
    gray = ImageOps.grayscale(img)
    return ImageOps.autocontrast(gray)


def ocr_image(path):
    img = Image.open(path)
    pre = preprocess(img)
    return pytesseract.image_to_string(pre)


def parse_amount(token):
    cleaned = token.replace(",", "")
    try:
        value = float(cleaned)
    except ValueError:
        return None
    return f"{value:.2f}"


def normalize_date(y, m, d):
    try:
        yi, mi, di = int(y), int(m), int(d)
    except ValueError:
        return None
    if yi < 100:
        yi += 2000
    if not (1 <= mi <= 12 and 1 <= di <= 31):
        return None
    if not (1990 <= yi <= 2099):
        return None
    return f"{yi:04d}-{mi:02d}-{di:02d}"


def extract_date(text):
    for line in text.splitlines():
        for pat, kind in DATE_PATTERNS:
            m = pat.search(line)
            if not m:
                continue
            if kind == "dmy":
                return normalize_date(m.group(3), m.group(2), m.group(1))
            if kind == "ymd":
                return normalize_date(m.group(1), m.group(2), m.group(3))
            if kind == "dmy2":
                return normalize_date(m.group(3), m.group(2), m.group(1))
            if kind == "dMy":
                month = MONTHS.get(m.group(2).lower())
                if month:
                    return normalize_date(m.group(3), month, m.group(1))
            if kind == "Mdy":
                month = MONTHS.get(m.group(1).lower())
                if month:
                    return normalize_date(m.group(3), month, m.group(2))
    return None


def line_excluded(line_upper):
    return any(kw in line_upper for kw in EXCLUSION_KEYWORDS)


def find_amount_on_line(line):
    matches = AMOUNT_RE.findall(line)
    if matches:
        return parse_amount(matches[-1])
    return None


def extract_total(text):
    lines = text.splitlines()
    for keywords in PRIORITY_KEYWORDS:
        for i, line in enumerate(lines):
            up = line.upper()
            if line_excluded(up):
                continue
            if not any(kw in up for kw in keywords):
                continue
            amount = find_amount_on_line(line)
            if amount is not None:
                return amount
            # Fallback: look at the next line
            for j in range(i + 1, min(i + 3, len(lines))):
                next_line = lines[j]
                if not next_line.strip():
                    continue
                nxt_amount = find_amount_on_line(next_line)
                if nxt_amount is not None:
                    return nxt_amount
                break
    return None


def process_images():
    rows = []
    for path in sorted(IMAGE_DIR.iterdir()):
        if path.suffix.lower() not in {".jpg", ".jpeg", ".png"}:
            continue
        text = ocr_image(path)
        date = extract_date(text)
        total = extract_total(text)
        rows.append((path.name, date, total))
        print(f"{path.name} -> date={date}, total={total}")
    return rows


def write_xlsx(rows):
    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for name, date, total in rows:
        ws.append([name, date, total])
    wb.save(OUTPUT_XLSX)


if __name__ == "__main__":
    rows = process_images()
    write_xlsx(rows)
    print(f"\nWritten {len(rows)} rows to {OUTPUT_XLSX}")
"}

