{"command": "create", "path": "/app/workspace/extract_receipts_v2.py", "file_text": """"Combined OCR extraction with multiple preprocessing passes."""
import os
import re
from pathlib import Path

import pytesseract
from openpyxl import Workbook
from PIL import Image, ImageEnhance, ImageFilter, ImageOps

IMAGE_DIR = Path("/app/workspace/dataset/img")
OUTPUT_XLSX = Path("/app/workspace/stat_ocr.xlsx")


# ----------------- OCR preprocessing variants -----------------

def preprocess_variants(img):
    """Yield (name, pil_image, psm) tuples."""
    w, h = img.size
    gray = ImageOps.grayscale(img)

    # Variant 1: gray + autocontrast (original)
    yield "gray_ac", ImageOps.autocontrast(gray), 3

    # Variant 2: 2x scaled gray + autocontrast
    scaled2 = gray.resize((w * 2, h * 2), Image.LANCZOS)
    yield "gray_2x_ac", ImageOps.autocontrast(scaled2), 6

    # Variant 3: median filter + 2x + autocontrast
    med = gray.filter(ImageFilter.MedianFilter(3))
    med_scaled = med.resize((w * 2, h * 2), Image.LANCZOS)
    yield "med_2x_ac", ImageOps.autocontrast(med_scaled), 6

    # Variant 4: contrast enhanced + 3x
    enhancer = ImageEnhance.Contrast(gray)
    hc = enhancer.enhance(3.0)
    hc_scaled = hc.resize((w * 2, h * 2), Image.LANCZOS)
    yield "contrast_2x", hc_scaled, 6

    # Variant 5: sharpened + 2x
    sharp = gray.filter(ImageFilter.SHARPEN)
    sharp_scaled = sharp.resize((w * 2, h * 2), Image.LANCZOS)
    yield "sharp_2x", ImageOps.autocontrast(sharp_scaled), 6


def run_ocr(image_path):
    """Run OCR with multiple preprocessing passes, return list of (name, text)."""
    img = Image.open(image_path)
    results = []
    for name, variant, psm in preprocess_variants(img):
        try:
            text = pytesseract.image_to_string(variant, config=f"--psm {psm}")
            results.append((name, text))
        except Exception:
            continue
    return results


# ----------------- Date extraction -----------------

MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

DATE_PATTERNS = [
    (re.compile(r"\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})\b"), "dmy"),
    (re.compile(r"\b(\d{4})[/\-\.](\d{1,2})[/\-\.](\d{1,2})\b"), "ymd"),
    (re.compile(r"\b(\d{2})(\d{2})(\d{4})\b"), "dmy_concat"),
    (re.compile(r"\b(\d{2})(\d{2})[/\-\.](\d{4})\b"), "dmcompact_y"),
    (re.compile(r"\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2})\b"), "dmy2"),
    (re.compile(r"\b(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{4})\b"), "dMy"),
    (re.compile(r"\b([A-Za-z]{3,9})\s+(\d{1,2})[,\s]+(\d{4})\b"), "Mdy"),
]


def normalize_date(y, m, d):
    try:
        yi, mi, di = int(y), int(m), int(d)
    except (ValueError, TypeError):
        return None
    if yi < 100:
        yi += 2000
    if not (1 <= mi <= 12 and 1 <= di <= 31):
        return None
    if not (2000 <= yi <= 2024):
        return None
    return f"{yi:04d}-{mi:02d}-{di:02d}"


def extract_dates_from_text(text):
    """Return a list of candidate dates (string ISO form) with their line context."""
    candidates = []
    for line in text.splitlines():
        for pat, kind in DATE_PATTERNS:
            for m in pat.finditer(line):
                date = None
                if kind == "dmy":
                    date = normalize_date(m.group(3), m.group(2), m.group(1))
                elif kind == "ymd":
                    date = normalize_date(m.group(1), m.group(2), m.group(3))
                elif kind == "dmy2":
                    date = normalize_date(m.group(3), m.group(2), m.group(1))
                elif kind == "dmy_concat":
                    date = normalize_date(m.group(3), m.group(2), m.group(1))
                elif kind == "dmcompact_y":
                    date = normalize_date(m.group(3), m.group(2), m.group(1))
                elif kind == "dMy":
                    month = MONTHS.get(m.group(2).lower())
                    if month:
                        date = normalize_date(m.group(3), month, m.group(1))
                elif kind == "Mdy":
                    month = MONTHS.get(m.group(1).lower())
                    if month:
                        date = normalize_date(m.group(3), month, m.group(2))
                if date:
                    candidates.append((date, line))
    return candidates


def pick_best_date(all_candidates):
    """Pick most frequent date from candidates across OCR variants.

    If a candidate line contains strong hints like 'DATE', 'BIZDATE', score higher.
    """
    if not all_candidates:
        return None
    scores = {}
    for date, line in all_candidates:
        up = line.upper()
        s = 1
        if "DATE" in up:
            s += 10
        if "BIZDATE" in up or "BILL DT" in up or "BILL DI" in up:
            s += 5
        if "INV" in up or "RECEIPT" in up:
            s += 3
        if "CLOSED" in up or "SERVER" in up:
            s += 1
        scores[date] = scores.get(date, 0) + s
    return max(scores.items(), key=lambda kv: (kv[1], kv[0]))[0]


# ----------------- Total extraction -----------------

AMOUNT_RE = re.compile(r"(?<![\d.])(\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|\d+\.\d{2})(?![\d])")


def parse_amount(token):
    cleaned = token.replace(",", "")
    try:
        value = float(cleaned)
    except ValueError:
        return None
    return f"{value:.2f}"


def find_amounts(line):
    return [parse_amount(m) for m in AMOUNT_RE.findall(line) if parse_amount(m)]


def line_is_excluded(line):
    up = line.upper()

    # Subtotal variants
    if re.search(r"\bSUB[\s\-]?TOTAL\b", up):
        return True
    # Excluding
    if "EXCLUDING" in up or re.search(r"\bEXCL\b", up):
        return True
    # Discount
    if "DISCOUNT" in up or re.search(r"\bDISC\b", up):
        return True
    # Change (as whole word)
    if re.search(r"\bCHANGE\b", up):
        return True
    # Cash tendered
    if re.search(r"CASH\s+TENDERED", up):
        return True
    # Tax Invoice title line
    if re.search(r"\bTAX\s+INVOICE\b", up):
        return True
    # Simplified Tax Invoice title
    if re.search(r"SIMPLIFIED\s+TAX", up):
        return True
    # "Total GST/TAX/SST" (adjacent, no words in between)
    if re.search(r"\bTOTAL\s*(?:GST|TAX|SST)\b", up):
        return True
    # Line starting with "GST/TAX/SST" (as primary subject)
    if re.search(r"^\s*\(?\s*(?:GST|TAX|SST)\s*[\)@%:0-9]", up):
        return True
    # Patterns like "GST Summary", "Tax Summary"
    if re.search(r"\b(?:GST|TAX|SST)\s+SUMMARY", up):
        return True
    # Patterns like "GST Payable" / "GST Amount"
    if re.search(r"\b(?:GST|TAX|SST)\s+PAYABLE", up):
        return True
    # Tax Total:
    if re.search(r"\bTAX\s+TOTAL\b", up):
        return True
    # Tax Code
    if re.search(r"\bTAX\s+CODE\b", up):
        return True
    # "TOTAL INCLUDES X% GST" is GST info, not total
    if re.search(r"INCLUDES?\s+\d+\s*%\s*(?:GST|TAX|SST)", up):
        return True
    # Rounding adjustment
    if re.search(r"\bROUNDING\b", up) and "ROUNDED" not in up:
        return True
    if re.search(r"\bROUND\s+ADJ", up):
        return True
    # "Total Qty" or "Total Quantity" or "Total Item"
    if re.search(r"\bTOTAL\s+(?:QTY|QUANTITY|ITEM)\b", up):
        return True
    # Column header "Amount(RM) Tax(RM)" from GST summary
    if re.search(r"AMOUNT\s*\(\s*RM\s*\)\s*TAX", up):
        return True
    if re.search(r"\bTAX\s*/\s*AMT\b", up):
        return True
    # Header-like line "ITEM QTY ... AMOUNT" or "QTY PRICE AMOUNT"
    if re.search(r"\b(?:ITEM|DESC(?:RIPTIOR)?|QTY)\b.*\bAMOUNT\b", up):
        return True
    if re.search(r"\b(?:ITEM|QTY)\b.*\bTOTAL\b", up):
        return True
    # Lines like "DESC QTY PRICE AMOUNT TAXCODE"
    if re.search(r"\bQTY\s+(?:TAX|RM|PRICE|S/PRICE)\b", up):
        return True
    # Numbers without decimals aren't amounts
    return False


PRIO1_RE = re.compile(r"\bGRAND\s+TOTAL\b", re.I)
PRIO2_RE = re.compile(r"\bTOTAL\s*:?\s*RM\b", re.I)
PRIO3_RE = re.compile(r"\bTOTAL\s+AMOUNT\b", re.I)
PRIO4_KEYWORDS = [
    r"\bGRAND\s+TOTAL\b",
    r"\b(?:NETT?|FINAL)\s+TOTAL\b",
    r"\bTOTAL\s+DUE\b",
    r"\bBALANCE\s+DUE\b",
    r"\bAMOUNT\s+DUE\b",
    r"\bTOTAL\s+AMT\s+PAYABLE\b",
    r"\bTOTAL\s+AMT\b",
    r"\bTOTAL\s+AFTER\b",
    r"\bTOTAL\s+INC(?:L(?:UDE|USIVE)?)?\b",
    r"\bTOTAL\s+ROUNDED\b",
    r"\bTAKEOUT\s+TOTAL\b",
    r"\bTOTAL\s+SALES?\s+(?:\(?\s*)?INCL(?:USIVE)?\b",
    r"\bTOTAL\b",
    r"\bAMOUNT\b",
]


def total_score(line):
    """Return a specificity score for a total candidate line."""
    up = line.upper()
    score = 0
    if PRIO1_RE.search(up):
        score = max(score, 100)
    if re.search(r"\b(?:NETT?|FINAL)\s+TOTAL\b", up):
        score = max(score, 95)
    if re.search(r"\bTOTAL\s+(?:AMT|AMOUNT)\s+PAYABLE\b", up):
        score = max(score, 93)
    if re.search(r"\bTOTAL\s+AMT\b", up):
        score = max(score, 93)
    if PRIO2_RE.search(up):
        score = max(score, 90)
    if PRIO3_RE.search(up):
        score = max(score, 88)
    if re.search(r"\bTOTAL\s+DUE\b", up):
        score = max(score, 88)
    if re.search(r"\bBALANCE\s+DUE\b", up):
        score = max(score, 88)
    if re.search(r"\bAMOUNT\s+DUE\b", up):
        score = max(score, 88)
    if re.search(r"\bTOTAL\s+AFTER\b", up):
        score = max(score, 85)
    if re.search(r"\bTOTAL\s+INC(?:L(?:UDE|USIVE)?)?\b", up):
        score = max(score, 80)
    if re.search(r"\bTAKEOUT\s+TOTAL\b", up):
        score = max(score, 80)
    if re.search(r"\bTOTAL\s+ROUNDED\b", up):
        score = max(score, 78)
    if re.search(r"\bTOTAL\s+SALES?\s+(?:\(?\s*)?INCL(?:USIVE)?\b", up):
        score = max(score, 75)
    # Simple "TOTAL" followed by colon or space then number
    if re.search(r"\bTOTAL\s*[:\s]\s*\d", up) and score < 60:
        score = max(score, 60)
    if re.search(r"\bTOTAL\b", up) and score < 50:
        score = max(score, 50)
    if re.search(r"\bAMOUNT\b", up) and score < 40:
        score = max(score, 40)
    return score


def extract_total_from_text(text):
    lines = text.splitlines()
    best_candidate = None  # (score, index, line, amount)
    for i, line in enumerate(lines):
        if not line.strip():
            continue
        if line_is_excluded(line):
            continue
        score = total_score(line)
        if score == 0:
            continue
        amounts = find_amounts(line)
        amount = amounts[-1] if amounts else None
        # If no amount on this line, try to peek next couple lines
        if amount is None:
